UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"Umbilical Venous Catheter (UVC)","body":"UVC PROCEDURE [1][2]\n\n**Umbilical cord anatomy:**\n• **2 arteries** — thick-walled, small lumen (at top of cross-section)\n• **1 vein** — thin-walled, large lumen (at bottom of cross-section)\n• **Catheterize the VEIN** — larger, easier to cannulate\n\n**Catheter size:**\n• **3.5 French** if <1.5 kg\n• **5 French** if ≥1.5 kg\n\n**Procedure:**\n1. Tie **umbilical tape** at base of stump — gentle tie to control bleeding\n2. Cut cord 1–2 cm above skin\n3. Identify the single large-lumen vein\n4. **Prime catheter** with NS\n5. Insert gently — **only 2–4 cm** until blood aspirates freely\n6. Do NOT advance further — risk of hepatic injury\n\n**IO access** is an acceptable alternative if UVC cannot be placed quickly.\n\n**Once access is established:** give IV epinephrine (preferred over ET route). [1][2]","citation":[1,2],"next":"nrp-persistent","images":[{"src":"images/neonatal-resus/uvc-anatomy.png","alt":"Umbilical cord cross-section showing 2 arteries and 1 vein, with side view of UVC insertion through umbilical stump — emergency insertion 2-4 cm, until free blood return","caption":"UVC anatomy: 2 arteries (thick, small) + 1 vein (thin, large). Emergency insertion: 2-4 cm, until blood aspirates freely."}],"calculatorLinks":[{"id":"neo-numbers","label":"Neonate Numbers (<3 kg)"}],"summary":"UVC: catheterize the single large VEIN (not arteries), 3.5 Fr if <1.5 kg, 5 Fr if ≥1.5 kg, insert only 2-4 cm until blood return, prime with NS"}'::jsonb
WHERE id = 'nrp-uvc' AND tree_id = 'neonatal-resus';

